-- G-LOKOO POS v1.1 - Staff, Roles & Audit
-- Run after all previous G-LOKOO migrations.

create or replace function public.current_user_role() returns text language sql stable security definer set search_path=public as $$ select coalesce((select role from public.profiles where id=auth.uid()),'cashier'); $$;
create or replace function public.is_management() returns boolean language sql stable security definer set search_path=public as $$ select public.current_user_role() in ('owner','admin'); $$;

create table if not exists public.audit_log(id bigint generated by default as identity primary key,actor_id uuid references auth.users(id) on delete set null,action text not null,table_name text,record_id text,details jsonb,created_at timestamptz not null default now());
alter table public.audit_log enable row level security;
drop policy if exists "management audit read" on public.audit_log; create policy "management audit read" on public.audit_log for select to authenticated using (public.is_management());
drop policy if exists "authenticated audit insert" on public.audit_log; create policy "authenticated audit insert" on public.audit_log for insert to authenticated with check (actor_id=auth.uid());
create or replace function public.write_audit(p_action text,p_table text,p_record_id text,p_details jsonb default '{}'::jsonb) returns void language plpgsql security definer set search_path=public as $$ begin insert into public.audit_log(actor_id,action,table_name,record_id,details) values(auth.uid(),p_action,p_table,p_record_id,p_details); end; $$;

drop policy if exists "authenticated profiles read" on public.profiles; create policy "authenticated profiles read" on public.profiles for select to authenticated using(true);
drop policy if exists "management profiles update" on public.profiles; create policy "management profiles update" on public.profiles for update to authenticated using(public.is_management()) with check(public.is_management());

drop policy if exists "authenticated products all" on public.products; create policy "authenticated products read" on public.products for select to authenticated using(true); create policy "inventory products insert" on public.products for insert to authenticated with check(public.current_user_role() in ('owner','admin','inventory')); create policy "inventory products update" on public.products for update to authenticated using(public.current_user_role() in ('owner','admin','inventory')) with check(public.current_user_role() in ('owner','admin','inventory')); create policy "management products delete" on public.products for delete to authenticated using(public.is_management());

drop policy if exists "authenticated customers all" on public.customers; create policy "sales customers read" on public.customers for select to authenticated using(public.current_user_role() in ('owner','admin','cashier')); create policy "sales customers insert" on public.customers for insert to authenticated with check(public.current_user_role() in ('owner','admin','cashier')); create policy "sales customers update" on public.customers for update to authenticated using(public.current_user_role() in ('owner','admin','cashier')) with check(public.current_user_role() in ('owner','admin','cashier')); create policy "management customers delete" on public.customers for delete to authenticated using(public.is_management());

drop policy if exists "authenticated expenses all" on public.expenses; create policy "management expenses read" on public.expenses for select to authenticated using(public.is_management()); create policy "management expenses insert" on public.expenses for insert to authenticated with check(public.is_management()); create policy "management expenses update" on public.expenses for update to authenticated using(public.is_management()) with check(public.is_management()); create policy "management expenses delete" on public.expenses for delete to authenticated using(public.is_management());

drop policy if exists "authenticated repairs all" on public.repairs; create policy "repair read" on public.repairs for select to authenticated using(public.is_management() or technician_id=auth.uid()); create policy "repair insert" on public.repairs for insert to authenticated with check(public.current_user_role() in ('owner','admin','technician')); create policy "repair update" on public.repairs for update to authenticated using(public.is_management() or technician_id=auth.uid()) with check(public.is_management() or technician_id=auth.uid()); create policy "management repair delete" on public.repairs for delete to authenticated using(public.is_management());

drop policy if exists "authenticated phone units read" on public.phone_units; create policy "authenticated phone units read" on public.phone_units for select to authenticated using(true); create policy "inventory phone units insert" on public.phone_units for insert to authenticated with check(public.current_user_role() in ('owner','admin','inventory')); create policy "inventory phone units update" on public.phone_units for update to authenticated using(public.current_user_role() in ('owner','admin','inventory')) with check(public.current_user_role() in ('owner','admin','inventory')); create policy "management phone units delete" on public.phone_units for delete to authenticated using(public.is_management());

create or replace function public.audit_profile_role_change() returns trigger language plpgsql security definer set search_path=public as $$ begin if old.role is distinct from new.role then perform public.write_audit('ROLE_CHANGED','profiles',new.id::text,jsonb_build_object('old_role',old.role,'new_role',new.role,'staff_name',new.full_name)); end if; return new; end; $$;
drop trigger if exists trg_audit_profile_role_change on public.profiles; create trigger trg_audit_profile_role_change after update of role on public.profiles for each row execute procedure public.audit_profile_role_change();
grant select on public.audit_log to authenticated;
